import sys


def min_tri_brute(tri):
    def dfs(i, j):
        if i == len(tri) - 1:
            return tri[i][j]
        return tri[i][j] + min(dfs(i + 1, j), dfs(i + 1, j + 1))
    return dfs(0, 0)


if __name__ == '__main__':
    data = sys.stdin.read().split()
