        sys.exit(0)
    n = int(data[0])
    tri = []
    idx = 1
    for i in range(1, n + 1):
        tri.append(list(map(int, data[idx:idx + i])))
        idx += i
    print(min_tri_brute(tri))

import sys


def min_tri_opt(tri):
    n = len(tri)
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = tri[0][0]
    for i in range(1, n):
        for j in range(i + 1):
            best = float('inf')
            if j < i:
                best = min(best, dp[i - 1][j])
            if j > 0:
                best = min(best, dp[i - 1][j - 1])
            dp[i][j] = tri[i][j] + best
    return min(dp[n - 1])


