import sys


def min_tri_best(tri):
    dp = tri[-1][:]
    for i in range(len(tri) - 2, -1, -1):
        for j in range(i + 1):
            dp[j] = tri[i][j] + min(dp[j], dp[j + 1])
    return dp[0]


